%[text] # Transmision automatica Fuzzy
%[text] Entradas velocidad y acelerador
%[text] Salida es la marcha ideal
%[text] Reglas tipo mamdani
%[text] ## Funciones de pertenenia
clear; clc; close all;
 
S.vmax = 200; %Velociad maxima en [km/h]
S.amax = 100; %Aceleración maxima en [%]
 
%Entrada 1: Velocidad
S.nomV = {'Muy baja', 'Baja', 'Media', 'Alta', 'Muy alta'};
S.fpV  = { 'trap', [0    0      0.075  0.20];   %   0 –  40 km/h
           'tri',  [0.075  0.20   0.375      ];   %  15 –  75 km/h
           'tri',  [0.20   0.375  0.55       ];   %  40 – 110 km/h
           'tri',  [0.375  0.55   0.75       ];   %  75 – 150 km/h
           'trap', [0.55   0.75   1      1  ]};  % 110 – 200 km/h
 
%Entrada 2: Aceleración
S.nomA = {'Suave', 'Medio', 'Fondo'};
S.fpA  = {'trap', [-1    0     0.20  0.50];
          'tri',  [0.20  0.50  0.85      ];
          'trap', [0.50  0.85  1     2   ]}; %Funciones de pertenencia acelerador
 
% Salida: Cambio ideal
S.Universo = linspace(0, 6, 601);
S.nomC = {'M1','M2','M3','M4','M5'};
S.fpC  = cell(5, 2);
for k = 1:5
    S.fpC(k, :) = {'tri', [k-1, k, k+1]}; %Funciones de pertenencia salida
end
 
% Precalcular las funciones de pertenencia de salida sobre el universo
S.muG = zeros(5, numel(S.Universo));
for k = 1:5
    S.muG(k, :) = pertenencia(S.Universo, S.fpC{k,1}, S.fpC{k,2});
end
 
%[text] ## Reglas
%A punto de bajar cambio | normal | A punto de subir cambio
S.reglas = [1 1 1;   1 2 1;   1 3 1;
            2 1 3;   2 2 2;   2 3 1;
            3 1 5;   3 2 3;   3 3 2;
            4 1 5;   4 2 4;   4 3 3;
            5 1 5;   5 2 5;   5 3 4];
 
%[text] ## Visualización de los conjuntos difusos
xs = linspace(0, 1, 500);
figure('Name', 'Funciones de pertenencia', 'Position', [50 400 1200 330]); %[output:612e06ed]
subplot(1,3,1); hold on; %[output:612e06ed]
 
for k = 1:numel(S.nomV)
    plot(xs*S.vmax, pertenencia(xs, S.fpV{k,1}, S.fpV{k,2}), 'LineWidth', 2); %[output:612e06ed]
end
 
title('Velocidad'); xlabel('v [km/h]'); ylabel('\mu'); legend(S.nomV); grid on; %[output:612e06ed]
subplot(1,3,2); hold on; %[output:612e06ed]
for k = 1:numel(S.nomA)
    plot(xs*S.amax, pertenencia(xs, S.fpA{k,1}, S.fpA{k,2}), 'LineWidth', 2); %[output:612e06ed]
end
title('Acelerador'); xlabel('a [%]'); ylabel('\mu'); legend(S.nomA); grid on; %[output:612e06ed]
subplot(1,3,3); plot(S.Universo, S.muG, 'LineWidth', 2); %[output:612e06ed]
title('Cambio ideal (salida)'); xlabel('z'); ylabel('\mu'); legend(S.nomC); grid on; %[output:612e06ed]
 
%[text] ## Superficie de control
vv = linspace(0, 200, 81);
aa = linspace(0, 100, 41);
[VV, AA] = meshgrid(vv, aa);
Z = zeros(size(VV));
for i = 1:numel(VV)
    Z(i) = Inferencia(S, VV(i), AA(i));
end
figure('Name', 'Superficie de control', 'Position', [50 50 650 480]); %[output:909905af]
surf(VV, AA, Z, 'EdgeColor', 'none'); colormap(parula); colorbar; %[output:909905af]
xlabel('Velocidad [km/h]'); ylabel('Pedal [%]'); zlabel('Cambio ideal z'); %[output:909905af]
title('Superficie de control Mamdani'); view(-125, 28); %[output:909905af]
 
%[text] ## Planta
car.m     = 1200;                          % masa [kg]
car.g0    = 9.81;                          % gravedad [m/s^2]
car.rw    = 0.30;                          % radio de rueda [m]
car.ig    = [3.50 2.10 1.40 1.00 0.80];    % relaciones de la caja (1a a 5a)
car.ifin  = 4.10;                          % relación del diferencial
car.eta   = 0.90;                          % eficiencia del tren motriz
car.Cd    = 0.32;  car.Af = 2.2;  car.rho = 1.2;   % aerodinámica
car.Crr   = 0.012;                         % resistencia a la rodadura
car.rpm_ralenti = 800;                     % rpm mínimas
car.rpm_max     = 6500;                    % limitador de revoluciones
car.Ffreno_max  = 8000;                    % fuerza de frenado máxima [N]
 
sel.tau       = 1.5;     % constante de tiempo del filtro del pedal [s]
sel.h         = 0.40;    % histéresis: sube si z > g+0.9, baja si z < g-0.9
sel.t_min     = 1.2;     % tiempo mínimo entre cambios [s]
sel.rpm_sobre = 6000;    % fuerza subida / bloquea bajada si se supera
sel.rpm_min   = 1100;    % bloquea subida si el motor quedaría ahogado
 
%[text] ## Controlador PI
drv.Kp = 0.12;  drv.Ki = 0.02; %Contrates

v_final    = 70;     % velocidad deseada [km/h]
t_llegada  = 20;     % tiempo en que se quiere alcanzar v_final [s]
pend_valor = 0;      % pendiente de la subida [%]  (0 = vía plana)
t_ini_pend = 30;     % inicio de la subida [s]
t_fin_pend = 50;     % fin de la subida [s]
 
%Parametros
dt = 0.01;           % paso de integración [s]
Tf = 70;             % tiempo total simulado [s]
N  = round(Tf/dt);   % número de pasos
 
L = struct('t',zeros(1,N),'v',zeros(1,N),'vref',zeros(1,N),'acel',zeros(1,N), ...
    'acf',zeros(1,N),'freno',zeros(1,N),'z',zeros(1,N),'g',zeros(1,N), ...
    'rpm',zeros(1,N),'pend',zeros(1,N));
v = 0;  integ = 0;  g = 1;  t_ult = -inf;  acf = 0;
 
for k = 1:N
    t = (k-1)*dt;

    v_ref = min(v_final*t/t_llegada, v_final);
    pend  = pend_valor*(t >= t_ini_pend && t < t_fin_pend);
 
    v_kmh = v*3.6;

    e = v_ref - v_kmh;
    u = drv.Kp*e + drv.Ki*integ;
    if (u > 0 && u < 1) || (u >= 1 && e < 0) || (u <= 0 && e > 0)
        integ = integ + e*dt;
    end
    acel  = min(max(u, 0), 1);
    freno = 0;
    if u < -0.05, freno = min(-u, 1); end
 
    acf = acf + dt/sel.tau*(acel - acf);
 
    z = Inferencia(S, v_kmh, 100*acf);
 
    if t - t_ult >= sel.t_min
        rpm_act = rpm_motor(v, g, car);
        rpm_sub = rpm_motor(v, min(g+1, 5), car);
        rpm_baj = rpm_motor(v, max(g-1, 1), car);
        if rpm_act > sel.rpm_sobre && g < 5                       % protección
            g = g + 1;  t_ult = t;
        elseif z > g + 0.5 + sel.h && g < 5 && rpm_sub > sel.rpm_min
            g = g + 1;  t_ult = t;
        elseif z < g - 0.5 - sel.h && g > 1 && rpm_baj < sel.rpm_sobre
            g = g - 1;  t_ult = t;
        end
    end
 
    theta = atan(pend/100);
    v = max(v + dinamica(v, g, acel, freno, theta, car)*dt, 0);
 
    L.t(k) = t;  L.v(k) = v_kmh;  L.vref(k) = v_ref;  L.acel(k) = 100*acel;
    L.acf(k) = 100*acf;  L.freno(k) = 100*freno;  L.z(k) = z;  L.g(k) = g;
    L.rpm(k) = rpm_motor(v, g, car);  L.pend(k) = pend;
end
 
%[text] ## Resultados
figure('Name', 'Simulación', 'Position', [100 100 1000 800]); %[output:43480937]
subplot(4,1,1); %[output:43480937]
yyaxis left;  plot(L.t, L.vref, 'k--', L.t, L.v, 'LineWidth', 1.8); ylabel('v [km/h]'); %[output:43480937]
yyaxis right; area(L.t, L.pend, 'FaceAlpha', 0.15, 'EdgeColor', 'none'); ylabel('Pendiente [%]'); ylim([0 30]); %[output:43480937]
legend('Referencia', 'Velocidad', 'Pendiente', 'Location', 'southeast'); grid on; %[output:43480937]
title('Transmisión automática con control difuso Mamdani'); %[output:43480937]
subplot(4,1,2); %[output:43480937]
plot(L.t, L.acel, L.t, L.acf, L.t, L.freno, 'LineWidth', 1.5); ylabel('[%]'); %[output:43480937]
legend('Pedal', 'Pedal filtrado (entrada FIS)', 'Freno'); grid on; %[output:43480937]
subplot(4,1,3); %[output:43480937]
plot(L.t, L.z, 'Color', [0.6 0.6 0.6]); hold on; %[output:43480937]
stairs(L.t, L.g, 'LineWidth', 2.2); ylabel('Marcha'); yticks(1:5); %[output:43480937]
legend('z (salida difusa)', 'Cambio engranado'); grid on; %[output:43480937]
subplot(4,1,4); %[output:43480937]
plot(L.t, L.rpm, 'LineWidth', 1.5); yline(car.rpm_max, 'r:'); %[output:43480937]
ylabel('Motor [rpm]'); xlabel('Tiempo [s]'); grid on; %[output:43480937]
 
idx = find(diff(L.g) ~= 0);
fprintf('\nCambios de marcha:\n'); %[output:2ffa3bf7]
for i = idx %[output:group:6ed16586]
    fprintf('  t=%6.2f s  %d->%d  v=%6.1f km/h  pedal_filt=%5.1f %%  pend=%2.0f %%  rpm=%5.0f\n', ... %[output:8e1bac2f]
        L.t(i+1), L.g(i), L.g(i+1), L.v(i), L.acf(i), L.pend(i), L.rpm(i)); %[output:8e1bac2f]
end %[output:group:6ed16586]
fprintf('RPM máx: %.0f   Error medio |v - vref|: %.2f km/h\n', ... %[output:group:343a377f] %[output:72ecf7b7]
    max(L.rpm), mean(abs(L.v - L.vref))); %[output:group:343a377f] %[output:72ecf7b7]
 
%[text] ## Funciones
function mu = pertenencia(x, tipo, p) %Grado de pertenencia en las rectas
    switch tipo
        case 'tri'
            mu = max(min((x - p(1))/(p(2) - p(1)), (p(3) - x)/(p(3) - p(2))), 0);
        case 'trap'
            mu = max(min(min((x - p(1))/(p(2) - p(1)), 1), (p(4) - x)/(p(4) - p(3))), 0);
        otherwise
            error('Tipo de función de pertenencia no soportado');
    end
end
 
function z = Inferencia(S, v, a)
%t_norm = AND = min
%s_norm = OR = max
 
%Normalización de la entrada
xn = min(max(v/S.vmax, 0), 1);
yn = min(max(a/S.amax, 0), 1);
 
%Valor de pertenencia de la entrada en cada conjunto difuso
muV = zeros(1, size(S.fpV, 1));
muA = zeros(1, size(S.fpA, 1));
 
for k = 1:numel(muV)
    muV(k) = pertenencia(xn, S.fpV{k,1}, S.fpV{k,2});
end
 
for k = 1:numel(muA)
    muA(k) = pertenencia(yn, S.fpA{k,1}, S.fpA{k,2});
end
 
%Inferencia
agregado = zeros(size(S.Universo));
 
for r = 1:size(S.reglas, 1) %15 valores
    %Mira el conjunto difuso y luego va a los valores de pertencencia a ver cual le corresponde y toma el minimo
    antecedente = min(muV(S.reglas(r,1)), muA(S.reglas(r,2))); %t_norm
    %Se obtiene el grado de activación de las reglas
    if antecedente > 0
        %Se recorta el conjunto de salida al valor de activación del antecedente
        recorte  = min(antecedente, S.muG(S.reglas(r,3), :)); %t_norm
 
        %Sobrepone lo que habia y lo nuevo
        agregado = max(agregado, recorte); %s_norm
    end
end
 
%Defuzzificación por centroide (Ponderación)
if sum(agregado) > 0
    z = sum(S.Universo .* agregado) / sum(agregado); %Calculo del centroide
else
    z = 1; %Si no se activa ninguna regla
end
 
%Escalado de la salida con función piso
z = min(max(z, 1), 5); %El cambio queda entre 1 y 5
end
 
function rpm = rpm_motor(v, g, car)
% Velocidad del motor [rpm] a partir de la velocidad del vehículo [m/s]
rpm = max(v/car.rw * car.ig(g) * car.ifin * 60/(2*pi), car.rpm_ralenti);
end
 
function T = torque_max(rpm)
% Curva de par a plena carga [N·m]: 160 N·m a 4000 rpm
rpm = min(max(rpm, 800), 6500);
T = 160 - 50*((rpm - 4000)/3200)^2;
end
 
function dvdt = dinamica(v, g, acel, freno, theta_inclinacion, car)
 
rpm = rpm_motor(v, g, car);
T = acel*torque_max(rpm);
 
if rpm >= car.rpm_max  %limitador
    T = 0;
end
F_trac = T*car.ig(g)*car.ifin*car.eta/car.rw;
F_aero = 0.5*car.rho*car.Cd*car.Af*v^2;
F_rod  = (v > 0.05)*car.Crr*car.m*car.g0*cos(theta_inclinacion);
F_pend = car.m*car.g0*sin(theta_inclinacion);
F_fr   = (v > 0.05)*freno*car.Ffreno_max;
dvdt = (F_trac - F_aero - F_rod - F_pend - F_fr)/car.m;
end
 
drawnow

